/// <summary>
/// Confirm-payment dialog (Clear France API v4.1 - 6.8/8.4): collection date, reporting flow and
/// one line per VAT rate, pre-filled with what is still outstanding. The split lines are the
/// caller's shared in-memory buffer - edits land directly in it. B2C is never derived; the user
/// selects it here, where the derived flow is only the starting point.
/// </summary>
[Form]
public class CELTConfirmPaymentDialog extends FormRun
{
    CELTReportingFlow selectedFlow;
    TransDate         selectedDate;
    boolean           eReportingEnabled;
}

public void run()
{
    super();

    CELTPaymentVatSplitTmp none;

    CollectionDateCtrl.dateValue(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
    element.updateTotal(none);
}

/// <summary>
/// Shares the caller's in-memory split lines with the form datasource. Call between init()
/// and run().
/// </summary>
/// <param name = "_splitTmp">pre-filled split buffer</param>
public void setSplitData(CELTPaymentVatSplitTmp _splitTmp)
{
    CELTPaymentVatSplitTmp.setTmpData(_splitTmp);
}

/// <summary>
/// Applies the derived reporting flow as the starting point. The flow selector is editable
/// only when the e-reporting capability is on.
/// </summary>
/// <param name = "_defaultFlow">derived flow</param>
/// <param name = "_eReportingEnabled">e-reporting capability</param>
public void setDefaults(CELTReportingFlow _defaultFlow, boolean _eReportingEnabled)
{
    eReportingEnabled = _eReportingEnabled;

    ReportingFlowCtrl.selection(_defaultFlow);
    ReportingFlowCtrl.enabled(_eReportingEnabled);
}

/// <summary>
/// Recomputes the running total, using the in-memory buffer for the row being edited - the
/// datasource has not written it yet when the field's modified() fires.
/// </summary>
/// <param name = "_current">the row being edited, or null</param>
public void updateTotal(CELTPaymentVatSplitTmp _current)
{
    CELTPaymentVatSplitTmp splitTmp;
    real                   total;

    splitTmp.setTmpData(CELTPaymentVatSplitTmp);

    while select splitTmp
    {
        if (_current.RecId != 0 && splitTmp.RecId == _current.RecId)
        {
            total += _current.AmountToReport;
        }
        else
        {
            total += splitTmp.AmountToReport;
        }
    }

    TotalCtrl.realValue(total);
}

/// <summary>
/// Validates and closes: a collection date is mandatory for the e-reporting flows (8.4), and
/// at least one line must carry an amount.
/// </summary>
public void okClicked()
{
    CELTPaymentVatSplitTmp splitTmp;
    boolean                anyAmount;

    CELTPaymentVatSplitTmp_ds.write();

    selectedFlow = ReportingFlowCtrl.selection();
    selectedDate = CollectionDateCtrl.dateValue();

    if (selectedFlow != CELTReportingFlow::EInvoicing && selectedDate == dateNull())
    {
        warning("@CELTLabels:LcNoCollectionDate");
        return;
    }

    splitTmp.setTmpData(CELTPaymentVatSplitTmp);
    while select splitTmp
    {
        if (splitTmp.AmountToReport != 0)
        {
            anyAmount = true;
            break;
        }
    }

    if (!anyAmount)
    {
        warning("@CELTLabels:LcNoAmounts");
        return;
    }

    element.closeOk();
}

/// <summary>
/// The total must move while typing: recompute from the in-memory row, because the
/// datasource writes the edited value only on row change.
/// </summary>
public boolean modified()
{
    boolean ret = super();

    element.updateTotal(CELTPaymentVatSplitTmp);

    return ret;
}
